INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('a76418ba-6a27-50e2-8f6c-56ae556a8aba', 1, $q$lnyanoy-kostyum-s-yubkoy-maksi$q$, $q$Льняной костюм с юбкой макси$q$, $q$Linen Maxi Suit$q$, 'tailoring', $q$Льняной жилет без рукавов и юбка макси в пол — летняя лёгкость. Натуральные пуговицы, подчёркнутая талия, без подклада.$q$, $q$A sleeveless linen vest and a floor-skimming maxi skirt, cut for summer ease. Natural buttons, a defined waist, unlined.$q$, $q$Костюм из двух частей, который держит форму весь день и не просит глажки после первого часа. Жилет без рукавов скроен по фигуре: вытачки собирают талию, натуральные пуговицы застёгиваются встык, пройма открытая — под него легко уходит футболка или ничего. Юбка макси падает от бедра ровным клином, длина закрывает щиколотку, шаг свободный. Лён взят плотный, с характерной фактурой: он не просвечивает на солнце и держит цвет после стирки. Без подклада — костюм остаётся дышащим в жару. Носится целиком как комплект и по отдельности: жилет садится на джинсы, юбка живёт с любым верхом.$q$, $q$A two-piece that holds its shape through the day and stops asking to be pressed after the first hour. The sleeveless vest is cut close — darts draw the waist in, natural buttons meet edge to edge, the armhole is open enough to take a tee underneath or nothing at all. The maxi skirt falls from the hip in a clean wedge, long enough to cover the ankle with the stride left free. The linen is a heavier weave with visible texture: it does not go sheer in sunlight and keeps its colour through washing. Unlined, so it stays breathable in heat. Wear it whole, or apart — the vest sits on jeans, the skirt takes any top.$q$, $q$Лён 30%, хлопок 30%, вискоза 20%, полиэстер 20%$q$, $q$Linen 30%, cotton 30%, viscose 20%, polyester 20%$q$, $q$Деликатная стирка в холодной воде$q$, $q$Machine wash cold, gentle$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1008989269-X.jpg$q$, $j$["/images/white/products/p-1008989269-b-X.jpg","/images/white/products/p-1008989269-3-X.jpg","/images/white/products/p-1008989269-s-X.jpg","/images/white/products/p-1008989269-d-X.jpg"]$j$::jsonb, NULL, 0) ON CONFLICT (id) DO NOTHING;
