INSERT INTO products (id, title, price, sale_price, image, images, category, sizes, model_id, color_key, color_hex, color_name_ru, color_name_en, nm, color, sku, stock_quantity, active, is_test, sort_order) VALUES ('wb-1008989268', $q$Льняной костюм с юбкой макси — Коричневый$q$, 8000, NULL, $q$/images/white/products/p-1008989269-brown-X.jpg$q$, $j$[{"src":"/images/white/products/p-1008989269-brown-b-X.jpg","alt":""},{"src":"/images/white/products/p-1008989269-brown-3-X.jpg","alt":""},{"src":"/images/white/products/p-1008989269-brown-s-X.jpg","alt":""},{"src":"/images/white/products/p-1008989269-brown-d-X.jpg","alt":""}]$j$::jsonb, 'tailoring', ARRAY['XS','S','M','L','XL'], 'a76418ba-6a27-50e2-8f6c-56ae556a8aba', $q$brown$q$, $q$#5c4433$q$, $q$Коричневый$q$, $q$Brown$q$, 1008989268, $q$brown$q$, 'WB-1008989268', 0, true, false, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('4b63e888-bc6b-5fed-b6a8-23237918c205', 2, $q$palto-pidzhak-pritalennoe$q$, $q$Пальто-пиджак приталенное$q$, $q$Fitted Blazer Coat$q$, 'outerwear', $q$Демисезонное пальто с кроем пиджака — чистые плечи без воротника и скульптурная талия на пуговицах. На подкладе.$q$, $q$A demi-season coat cut like a blazer — clean collarless shoulders and a sculpted, buttoned waist. Fully lined.$q$, $q$Демисезонное пальто, скроенное по логике пиджака: плечо чистое, без воротника, линия горловины открытая. Талия собрана и застёгнута на пуговицы — силуэт получается скульптурный, а не прямой. Длина до середины бедра, рукав полный. Шерстяная смесь держит форму на весу и не мнётся в рукаве после дня в машине. Полностью на подкладе: надевается поверх свитера без сопротивления, снимается одним движением. Это пальто для города в +5…+15 — под него уходит и тонкий трикотаж, и рубашка, а сверху ничего не нужно.$q$, $q$A demi-season coat built on blazer logic: a clean shoulder, no collar, an open neckline. The waist is drawn in and buttoned, so the silhouette sculpts rather than falls straight. It ends mid-thigh with a full sleeve. The wool blend keeps its shape on the hanger and does not crease at the elbow after a day in the car. Fully lined — it goes over a sweater without fighting you and comes off in one motion. A coat for the city between +5 and +15: fine knitwear or a shirt underneath, nothing needed on top.$q$, $q$Шерсть 60%, кашемир 20%, полиэстер 15%, вискоза 5%$q$, $q$Wool 60%, cashmere 20%, polyester 15%, viscose 5%$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-795522033-Q.jpg$q$, $j$["/images/white/products/p-795522033-b-Q.jpg","/images/white/products/p-795522033-3-Q.jpg","/images/white/products/p-795522033-s-Q.jpg","/images/white/products/p-795522033-d-Q.jpg"]$j$::jsonb, NULL, 1) ON CONFLICT (id) DO NOTHING;
