INSERT INTO products (id, title, price, sale_price, image, images, category, sizes, model_id, color_key, color_hex, color_name_ru, color_name_en, nm, color, sku, stock_quantity, active, is_test, sort_order) VALUES ('wb-795327858', $q$Пальто-пиджак приталенное — Коричневый$q$, 23000, NULL, $q$/images/white/products/p-795522033-brown-Q.jpg$q$, $j$[{"src":"/images/white/products/p-795522033-brown-b-Q.jpg","alt":""},{"src":"/images/white/products/p-795522033-brown-3-Q.jpg","alt":""},{"src":"/images/white/products/p-795522033-brown-s-Q.jpg","alt":""},{"src":"/images/white/products/p-795522033-brown-d-T.jpg","alt":""}]$j$::jsonb, 'outerwear', ARRAY['XS','S','M','L','XL'], '4b63e888-bc6b-5fed-b6a8-23237918c205', $q$brown$q$, $q$#5c4433$q$, $q$Коричневый$q$, $q$Brown$q$, 795327858, $q$brown$q$, 'WB-795327858', 0, true, false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('cd87983c-7b1e-5815-9b1e-1a5ad5d4f4ce', 3, $q$zhilet-kostyumnyy-s-baskoy$q$, $q$Жилет костюмный с баской$q$, $q$Peplum Suit Vest$q$, 'tailoring', $q$Классический костюмный жилет с баской и застёжкой на пуговицы. Приталенный, острый поверх чего угодно.$q$, $q$A classic tailored vest with a peplum flare and a buttoned front. Nipped at the waist, sharp over anything.$q$, $q$Классический костюмный жилет, у которого работа сделана в крое, а не в отделке. Баска отходит от талии мягкой волной и прикрывает бедро — силуэт читается как песочные часы даже поверх прямых брюк. Перед застёгивается на пуговицы, спина цельная, пройма высокая: жилет не съезжает, когда поднимаешь руки. Хлопковая смесь плотная, с матовой поверхностью, держит острые линии. Носится как самостоятельный верх — с брюками в тон получается костюм, с джинсами выходит контраст, поверх рубашки читается как жилет от тройки.$q$, $q$A tailored vest where the work sits in the cut rather than the trim. The peplum leaves the waist in a soft wave and covers the hip, so the line reads as an hourglass even over straight trousers. The front buttons through, the back is whole, the armhole is high — it does not ride up when you raise your arms. A dense cotton blend with a matte surface that holds a sharp edge. Wear it as a top in its own right: matching trousers make it a suit, jeans make it a contrast, over a shirt it reads as the third piece.$q$, $q$Костюмная ткань: полиэстер 55%, вискоза 40%, эластан 5%$q$, $q$Suiting: polyester 55%, viscose 40%, elastane 5%$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-962827637-B.jpg$q$, $j$["/images/white/products/p-962827637-b-F.jpg","/images/white/products/p-962827637-3-F.jpg","/images/white/products/p-962827637-s-F.jpg","/images/white/products/p-962827637-d-F.jpg"]$j$::jsonb, NULL, 2) ON CONFLICT (id) DO NOTHING;
