INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('34fb861d-40e3-5009-9990-119c777edf2f', 4, $q$svitshot-s-bantikami$q$, $q$Свитшот с бантиками$q$, $q$Bow Sweatshirt$q$, 'knitwear', $q$Оверсайз-свитшот из хлопка, смягчённый бантиками. Приспущенное плечо, рубчатые края, мягкий хлопок.$q$, $q$An oversized cotton sweatshirt softened with bow details. Dropped shoulders, ribbed trims, soft cotton.$q$, $q$Свитшот свободного кроя, смягчённый бантиками по линии рукава. Плечо приспущено, объём есть, но он не тянет вниз: рубчатые манжеты и низ собирают форму и не дают вещи расползтись после стирки. Хлопковая смесь с мягкой изнанкой — надевается на голое тело без раздражения. Длина закрывает пояс, поэтому свитшот одинаково живёт с юбкой-баллон, прямыми джинсами и брюками с высокой посадкой. Лента продета через ткань и завязана поверх, поэтому рукав остаётся закрытым.$q$, $q$A relaxed sweatshirt softened with bows along the sleeve. The shoulder is dropped and the volume is there, but it does not drag: ribbed cuffs and hem gather the shape and keep it from spreading after washing. A cotton blend with a soft inside face — it goes on bare skin without scratching. It covers the waistband, which is why it sits equally well with a balloon skirt, straight jeans or high-rise trousers. The bows are stitched by hand and do not catch under a coat.$q$, $q$Хлопок 70%, полиэстер 30%$q$, $q$Cotton 70%, polyester 30%$q$, $q$Машинная стирка в холодной воде$q$, $q$Machine wash cold$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-442577291-I.jpg$q$, $j$["/images/white/products/p-442577291-c-I.jpg","/images/white/products/p-442577291-3-I.jpg","/images/white/products/p-442577291-b-I.jpg","/images/white/products/p-442577291-s-I.jpg","/images/white/products/p-442577291-d-M.jpg"]$j$::jsonb, NULL, 3) ON CONFLICT (id) DO NOTHING;
