INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('c9d4e12a-73cd-572f-9bce-975999ebb937', 5, $q$yubka-karandash-s-kruzhevnym-podyubnikom$q$, $q$Юбка карандаш с кружевным подъюбником$q$, $q$Lace-Hem Pencil Skirt$q$, 'skirts', $q$Длинная юбка карандаш с кружевным подъюбником, который выходит из-под низа. Офисная дисциплина с одной незастёгнутой деталью.$q$, $q$A long pencil skirt with a lace underskirt showing at the hem. Office discipline, with one thing left undone.$q$, $q$Юбка карандаш удлинённого кроя: низ падает ниже середины голени, тогда как короткая садилась бы на колено и весь день просила бы себя одёрнуть. Широкий пояс стоит высоко и держит, передняя половина идёт гладко, сзади заложена шлица — шаг не укорачивается. Кружевной подъюбник втачан, а не надет сверху, и выходит на ширину ладони из-под низа: спереди читается как отделка, со спины — как весь смысл вещи. Полотно плотное, полиэстер с вискозой и эластаном: держит складку, не лоснится на посадке и тянется, когда садишься. Берёт заправленную рубашку и выпущенный трикотаж.$q$, $q$A pencil skirt cut long — the hem falls below the calf, where a shorter one would stop at the knee and ask to be pulled down all day. A wide waistband sits high and holds; the front is flat, the back takes a vent so the stride is not shortened. The lace underskirt is stitched in, not layered on, and shows a hand’s width below the hem: from the front it reads as a finish, from behind as the whole point. The cloth is a dense polyester-viscose with elastane — it holds a crease, does not shine at the seat and gives when you sit down. It takes a shirt tucked in and a knit left out.$q$, $q$Полиэстер 55%, вискоза 40%, эластан 5%$q$, $q$Polyester 55%, viscose 40%, elastane 5%$q$, $q$Деликатная стирка при 30°$q$, $q$Machine wash cold, gentle$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1217814224-black-D.jpg$q$, $j$["/images/white/products/p-1217814224-black-b-D.jpg","/images/white/products/p-1217814224-black-3-D.jpg","/images/white/products/p-1217814224-black-s-D.jpg","/images/white/products/p-1217814224-black-d-D.jpg"]$j$::jsonb, $q$aw26$q$, 4) ON CONFLICT (id) DO NOTHING;
