INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('40d54288-ee7d-58eb-8b34-ab16cff670c5', 6, $q$korset-vecherniy-s-baskoy$q$, $q$Корсет вечерний с баской$q$, $q$Peplum Evening Corset$q$, 'dresses', $q$Структурный вечерний корсет с баской. Лиф на косточках и чёткая талия — создан для выхода.$q$, $q$A structured evening corset with a peplum hem. A boned bodice and a defined waist, made to be dressed up.$q$, $q$Вечерний корсет со структурой: лиф на косточках держит спину прямо и очерчивает талию, баска мягко расходится от неё и прикрывает переход к юбке или брюкам. Верх ровный, без бретелей — линия плеча остаётся открытой. Хлопковая смесь плотная, не тянется, поэтому силуэт не плывёт к концу вечера. Застёжка сзади. Это верх для выхода: с атласной юбкой-баллон получается вечерний комплект, с прямыми брюками — костюм для ужина, под пальто на плечах уходит целиком.$q$, $q$An evening corset with real structure: the boned bodice keeps the back straight and marks the waist, and the peplum spreads softly from it to cover the join with a skirt or trousers. The top edge is straight and strapless, leaving the shoulder line open. A dense cotton blend with no stretch, so the silhouette does not drift by the end of the night. It fastens at the back. This is a going-out top: a satin balloon skirt makes it evening, straight trousers make it dinner, and it disappears under a coat worn over the shoulders.$q$, $q$Полиэстер 65%, вискоза 30%, эластан 5%$q$, $q$Polyester 65%, viscose 30%, elastane 5%$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-675104410-N.jpg$q$, $j$["/images/white/products/p-675104410-b-R.jpg","/images/white/products/p-675104410-p-N.jpg","/images/white/products/p-675104410-t-R.jpg","/images/white/products/p-675104410-d-N.jpg"]$j$::jsonb, NULL, 5) ON CONFLICT (id) DO NOTHING;
