INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('e31eee8b-4ee2-558c-b5e6-7bc84bd10efb', 7, $q$bryuki-alladiny$q$, $q$Брюки алладины$q$, $q$Draped Harem Trousers$q$, 'tailoring', $q$Мягко драпированные брюки алладины со свободным силуэтом и чистой талией. Лёгкий тайлоринг на каждый день.$q$, $q$Softly draped harem trousers with a relaxed fall and a clean waist. Easy tailoring for every day.$q$, $q$Брюки алладины с мягкой драпировкой: ткань собирается на поясе и уходит вниз крупными складками, а к щиколотке силуэт сужается. Посадка высокая, пояс эластичный — брюки садятся по фигуре без пуговиц и молний и не давят после еды. Вискозная смесь тяжёлая на ощупь, поэтому складки лежат, а не топорщатся. Длина до косточки: под кроссовки, лодочки и босоножки. Это брюки на каждый день, которые выглядят как вечерние — с жилетом получается тайлоринг, с футболкой отдых.$q$, $q$Harem trousers with a soft drape: the cloth gathers at the waist, falls in large folds and narrows towards the ankle. The rise is high and the waistband elastic — they sit on the body with no buttons or zips and do not press after a meal. The viscose blend is weighty in the hand, so the folds lie rather than stick out. They end at the ankle bone, ready for trainers, courts or sandals. Everyday trousers that read as evening ones: a vest makes them tailoring, a t-shirt makes them rest.$q$, $q$Японский шёлк: хлопок 40%, вискоза 40%, эластан 20%$q$, $q$Japanese silk: cotton 40%, viscose 40%, elastane 20%$q$, $q$Машинная стирка в холодной воде$q$, $q$Machine wash cold$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-962783109-R.jpg$q$, $j$["/images/white/products/p-962783109-b-K.jpg","/images/white/products/p-962783109-3-R.jpg","/images/white/products/p-962783109-s-R.jpg","/images/white/products/p-962783109-d-K.jpg"]$j$::jsonb, NULL, 6) ON CONFLICT (id) DO NOTHING;
