INSERT INTO products (id, title, price, sale_price, image, images, category, sizes, model_id, color_key, color_hex, color_name_ru, color_name_en, nm, color, sku, stock_quantity, active, is_test, sort_order) VALUES ('wb-962783113', $q$Брюки алладины — Розовый$q$, 7500, NULL, $q$/images/white/products/p-962783109-rose-R.jpg$q$, $j$[{"src":"/images/white/products/p-962783109-rose-b-L.jpg","alt":""},{"src":"/images/white/products/p-962783109-rose-3-R.jpg","alt":""},{"src":"/images/white/products/p-962783109-rose-s-R.jpg","alt":""},{"src":"/images/white/products/p-962783109-rose-d-P.jpg","alt":""}]$j$::jsonb, 'tailoring', ARRAY['XS','S','M','L','XL'], 'e31eee8b-4ee2-558c-b5e6-7bc84bd10efb', $q$rose$q$, $q$#d9aca4$q$, $q$Розовый$q$, $q$Rose$q$, 962783113, $q$rose$q$, 'WB-962783113', 0, true, false, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('bd5db5fd-3c6b-5a71-97f5-dfeb054c524d', 8, $q$yubka-ballon-atlasnaya$q$, $q$Юбка баллон атласная$q$, $q$Satin Balloon Skirt$q$, 'skirts', $q$Атласная юбка-баллон мини с шортами и округлым объёмом. Матовый блеск, форма держит объём.$q$, $q$A satin balloon mini with built-in shorts and a rounded volume. Matte sheen, holds its volume.$q$, $q$Атласная юбка-баллон с округлым объёмом: подол собран внутрь, и юбка держит форму сама, без подъюбника. Внутри вшиты шорты — можно садиться, идти по ветру и не думать о длине. Посадка высокая, пояс на резинке. Атлас матовый, с приглушённым блеском: он ловит свет по изгибу, но не выглядит нарядно-глянцевым, поэтому юбка работает и днём. Длина мини. С корсетом получается вечер, со свитшотом — обычная суббота, с плотными колготками уходит в осень.$q$, $q$A satin balloon skirt with a rounded volume: the hem is gathered inward, so it holds its shape without a petticoat. Shorts are built in — sit down, walk into the wind, stop thinking about the length. High rise, elasticated waistband. The satin is matte with a muted sheen: it catches light along the curve without looking glossy, which is what lets the skirt work in daylight. Mini length. A corset makes it evening, a sweatshirt makes it an ordinary Saturday, opaque tights take it into autumn.$q$, $q$Атлас, полиэстер$q$, $q$Satin, polyester$q$, $q$Машинная стирка в холодной воде$q$, $q$Machine wash cold$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-371980450-V.jpg$q$, $j$["/images/white/products/p-371980450-b-V.jpg","/images/white/products/p-371980450-3-V.jpg","/images/white/products/p-371980450-back-A.jpg","/images/white/products/p-371980450-d-Y.jpg"]$j$::jsonb, NULL, 7) ON CONFLICT (id) DO NOTHING;
