INSERT INTO products (id, title, price, sale_price, image, images, category, sizes, model_id, color_key, color_hex, color_name_ru, color_name_en, nm, color, sku, stock_quantity, active, is_test, sort_order) VALUES ('wb-379323231', $q$Юбка баллон атласная — Серый$q$, 2250, NULL, $q$/images/white/products/p-371980450-grey-V.jpg$q$, $j$[{"src":"/images/white/products/p-371980450-grey-b-V.jpg","alt":""},{"src":"/images/white/products/p-371980450-grey-3-V.jpg","alt":""},{"src":"/images/white/products/p-371980450-grey-back-A.jpg","alt":""},{"src":"/images/white/products/p-371980450-grey-d-Y.jpg","alt":""}]$j$::jsonb, 'skirts', ARRAY['XS','S','M','L','XL'], 'bd5db5fd-3c6b-5a71-97f5-dfeb054c524d', $q$grey$q$, $q$#9a958d$q$, $q$Серый$q$, $q$Grey$q$, 379323231, $q$grey$q$, 'WB-379323231', 0, true, false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('66f03cba-d867-5669-9e4d-ffb123d1844d', 9, $q$rubashka-oversayz-s-kruzhevom$q$, $q$Рубашка оверсайз с кружевом$q$, $q$Lace Oversized Shirt$q$, 'dresses', $q$Оверсайз-рубашка с объёмным рукавом — кулиска с завязками у запястья, узкое кружево по краю манжеты. Свободные плечи, скруглённый низ.$q$, $q$An oversized shirt with a dramatic gathered sleeve — drawn at the wrist with a drawstring tie, a narrow lace edging showing at the cuff. Relaxed shoulders, a curved shirttail hem.$q$, $q$Рубашка свободного кроя с драматичным рукавом: у запястья он собран на кулиску с завязками, из-под манжеты выходит узкое кружево. Плечо приспущено, объём по корпусу большой, низ скруглён — рубашка одинаково хорошо заправляется и остаётся навыпуск. Хлопок мягкий, с лёгкой мятой фактурой, которая не требует утюга. Застёжка на пуговицы по всей длине. Носится на джинсы, поверх платья как лёгкий верхний слой и в качестве пляжной накидки. Рукав — главное в этой вещи, поэтому пальто поверх лучше надевать свободное.$q$, $q$An oversized shirt with a dramatic sleeve: gathered at the wrist on a drawstring tie, with a narrow lace edging showing below the cuff. The shoulder is dropped, the body is generous, the hem is curved — it tucks in and hangs out equally well. Soft cotton with a lightly crumpled texture that never asks for an iron. Buttons through. Wear it over jeans, over a dress as a light layer, or as a cover-up. The sleeve is the point of this shirt, so anything worn over it is better cut loose.$q$, $q$Хлопок 100%$q$, $q$Cotton 100%$q$, $q$Ручная стирка в холодной воде$q$, $q$Hand wash cold$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1113526969-H.jpg$q$, $j$["/images/white/products/p-1113526969-c-H.jpg","/images/white/products/p-1113526969-3-H.jpg","/images/white/products/p-1113526969-b-H.jpg","/images/white/products/p-1113526969-s-H.jpg","/images/white/products/p-1113526969-d-H.jpg"]$j$::jsonb, NULL, 8) ON CONFLICT (id) DO NOTHING;
