INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('e1878770-4bd8-525a-b960-b02ad4f88ec8', 10, $q$yubka-shorty-zamshevaya$q$, $q$Юбка-шорты замшевая$q$, $q$Suede Skort$q$, 'skirts', $q$Замшевая юбка-шорты с кружевной отделкой по низу — лёгкость шорт под линией юбки. Мягкая фактура, эластичный пояс.$q$, $q$A suede mini skort finished with a scalloped lace hem — the ease of shorts under the line of a skirt. Soft hand, elasticated waist.$q$, $q$Замшевая юбка-шорты: снаружи читается как юбка, внутри вшиты шорты — можно садиться, наклоняться и подниматься по лестнице, не поправляя. По низу идёт кружевная отделка с фестонами, она смягчает прямой замшевый силуэт. Пояс на резинке, посадка высокая. Искусственная замша мягкая, с бархатистой поверхностью, которая держит цвет и не тянется на бедре. Длина мини, крой А-силуэт. С плотными колготками и высокими сапогами уходит в холод, с футболкой остаётся летней.$q$, $q$A suede skort: a skirt from the outside, shorts built in underneath — sit, bend, take the stairs without adjusting anything. Scalloped lace runs along the hem and softens the straight suede line. Elasticated waistband, high rise. The faux suede is soft with a velvety surface that keeps its colour and does not stretch across the hip. Mini length, A-line. Opaque tights and tall boots take it into the cold; a t-shirt keeps it summer.$q$, $q$Полиэстер 55%, вискоза 40%, эластан 5%$q$, $q$Polyester 55%, viscose 40%, elastane 5%$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1143078000-N.jpg$q$, $j$["/images/white/products/p-1143078000-b-N.jpg","/images/white/products/p-1143078000-3-N.jpg","/images/white/products/p-1143078000-s-N.jpg","/images/white/products/p-1143078000-d-N.jpg"]$j$::jsonb, NULL, 9) ON CONFLICT (id) DO NOTHING;
