INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('abfd9fed-78e9-5d82-ab53-000d789ace92', 11, $q$palto-oversayz-s-poyasom$q$, $q$Пальто оверсайз с поясом$q$, $q$Long Belted Coat$q$, 'outerwear', $q$Длинное оверсайз-пальто демисезона с поясом. Приспущенное плечо, глубокий воротник, длина в пол.$q$, $q$A long oversized demi-season coat with a self-tie belt. Dropped shoulders, a deep collar, floor-skimming.$q$, $q$Длинное пальто оверсайз с поясом — тот случай, когда объём задуман, а не случился. Плечо приспущено, воротник глубокий, длина в пол закрывает всё, что надето снизу. Пояс завязывается на талии и собирает силуэт, а без него пальто читается как прямой халат: две вещи в одной. Шерстяная смесь плотная, держит тепло и не продувается на ветру. Полностью на подкладе, карманы глубокие. Демисезон и мягкая зима — под него уходит свитер крупной вязки без чувства тесноты.$q$, $q$A long oversized coat with a belt — volume by design rather than by accident. The shoulder is dropped, the collar deep, and the floor-skimming length covers whatever is underneath. Tie the belt and the silhouette gathers at the waist; leave it and the coat reads as a straight robe. Two garments in one. The wool blend is dense, holds warmth and does not let the wind through. Fully lined, with deep pockets. For demi-season and a mild winter: a chunky knit goes under it without any sense of crowding.$q$, $q$Шерсть 60%, кашемир 20%, полиэстер 15%, вискоза 5%$q$, $q$Wool 60%, cashmere 20%, polyester 15%, viscose 5%$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-100797221-C.jpg$q$, $j$["/images/white/products/p-100797221-b-C.jpg","/images/white/products/p-100797221-3-C.jpg","/images/white/products/p-100797221-s-C.jpg","/images/white/products/p-100797221-d-C.jpg"]$j$::jsonb, NULL, 10) ON CONFLICT (id) DO NOTHING;
