INSERT INTO products (id, title, price, sale_price, image, images, category, sizes, model_id, color_key, color_hex, color_name_ru, color_name_en, nm, color, sku, stock_quantity, active, is_test, sort_order) VALUES ('wb-814720607', $q$Пальто оверсайз с поясом — Коричневый в полоску$q$, 23000, NULL, $q$/images/white/products/p-100797221-stripe-C.jpg$q$, $j$[{"src":"/images/white/products/p-100797221-stripe-b-C.jpg","alt":""},{"src":"/images/white/products/p-100797221-stripe-3-C.jpg","alt":""},{"src":"/images/white/products/p-100797221-stripe-s-C.jpg","alt":""},{"src":"/images/white/products/p-100797221-stripe-d-C.jpg","alt":""}]$j$::jsonb, 'outerwear', ARRAY['XS','S','M','L','XL'], 'abfd9fed-78e9-5d82-ab53-000d789ace92', $q$charcoal$q$, $q$#3a3632$q$, $q$Коричневый в полоску$q$, $q$Brown pinstripe$q$, 814720607, $q$charcoal$q$, 'WB-814720607', 0, true, false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('bcc02642-14d4-5b9e-9840-30556ce1316d', 15, $q$palto-kimono-drapovoe$q$, $q$Пальто кимоно драповое$q$, $q$Draped Kimono Coat$q$, 'outerwear', $q$Драповое пальто кимоно с поясом и текучим силуэтом. Плотный драп держит форму, силуэт двигается вместе с вами.$q$, $q$A draped wool kimono coat with a belt and a fluid fall. Heavy wool holds the shape; the silhouette moves with you.$q$, $q$Драповое пальто кимоно с поясом: широкий рукав, мягкое плечо, текучий силуэт без жёстких линий. Драп плотный и тяжёлый — он держит форму весом ткани, а не подкладными деталями, поэтому пальто садится по фигуре и падает ровно. Пояс завязывается свободно, длина до бедра. Тепло для настоящей осени и мягкой зимы. Крой кимоно даёт свободу в плечах: под пальто уходит объёмный свитер, и силуэт не ломается.$q$, $q$A draped wool kimono coat with a belt: a wide sleeve, a soft shoulder, a fluid line with no hard edges. The wool is heavy and holds its shape by the weight of the cloth rather than by internal structure, so it settles on the body and falls straight. The belt ties loosely; the length sits at the hip. Warm enough for a real autumn and a mild winter. The kimono cut leaves the shoulders free — an oversized sweater goes underneath without breaking the line.$q$, $q$Шерсть 60%, кашемир 20%, полиэстер 15%, вискоза 5%$q$, $q$Wool 60%, cashmere 20%, polyester 15%, viscose 5%$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-795640219-Q.jpg$q$, $j$["/images/white/products/p-795640219-b-Q.jpg","/images/white/products/p-795640219-3-Q.jpg","/images/white/products/p-795640219-s-Q.jpg","/images/white/products/p-795640219-d-Q.jpg"]$j$::jsonb, NULL, 11) ON CONFLICT (id) DO NOTHING;
