INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('adca36d9-19f4-5c54-b4c5-04d149fca939', 16, $q$palto-kimono-korotkoe$q$, $q$Пальто кимоно короткое$q$, $q$Short Kimono Coat$q$, 'outerwear', $q$Укороченное пальто кимоно с чистыми линиями и мягким плечом. Лёгкий верхний слой без объёма.$q$, $q$A cropped kimono coat with clean lines and a soft shoulder. A light top layer with no bulk.$q$, $q$Укороченное пальто кимоно с чистыми линиями и мягким плечом. Крой минимальный: широкая пройма, прямой силуэт, запáх без застёжки. Длина до бедра — пальто заканчивается там, где начинается юбка или брюки, и не перерезает фигуру. Шерстяная смесь средней плотности, для прохладного лета и ранней осени. Это завершающий слой к образу, а не защита от холода: он добавляет структуру лёгкому платью и собирает свободный низ.$q$, $q$A cropped kimono coat with clean lines and a soft shoulder. The cut is minimal: a wide armhole, a straight line, a wrap front with no fastening. Hip length — it ends where a skirt or trousers begin and does not cut the figure in half. A mid-weight wool blend for a cool summer and early autumn. This is the finishing layer to an outfit rather than protection from cold: it gives structure to a light dress and gathers a loose bottom half.$q$, $q$Шерсть 60%, кашемир 20%, полиэстер 15%, вискоза 5%$q$, $q$Wool 60%, cashmere 20%, polyester 15%, viscose 5%$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-795670341-Q.jpg$q$, $j$["/images/white/products/p-795670341-3-Q.jpg","/images/white/products/p-795670341-b-Q.jpg","/images/white/products/p-795670341-s-Q.jpg","/images/white/products/p-795670341-d-Q.jpg"]$j$::jsonb, NULL, 12) ON CONFLICT (id) DO NOTHING;
