INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('8afdc085-2d49-5caa-836d-720e0adc4a82', 18, $q$zhilet-s-baskoy-i-kruzhevom$q$, $q$Жилет с баской и кружевом$q$, $q$Lace Peplum Vest$q$, 'tailoring', $q$Костюмный жилет с баской, завершённый кружевом. Острота тайлоринга, смягчённая по краю.$q$, $q$A tailored peplum vest finished with lace. The sharpness of tailoring, softened at the edge.$q$, $q$Костюмный жилет с баской, завершённый кружевом по нижнему краю. Крой строгий: структурное плечо, V-образный вырез, застёжка на четыре пуговицы, талия собрана вытачками. Баска расходится мягко и прикрывает бедро. Кружево с фестонами идёт по самому низу и снимает с жилета офисную сухость — вещь читается вечерней, оставаясь по крою деловой. Шерстяная смесь плотная, держит линию плеча. Носится с прямыми брюками как костюм, с джинсами как контраст и поверх тонкой водолазки зимой.$q$, $q$A tailored peplum vest finished with lace along the bottom edge. The cut is strict: a structured shoulder, a V-neckline, a four-button front, a waist drawn in with darts. The peplum spreads softly and covers the hip. Scalloped lace runs along the very hem and takes the office dryness out of it — the piece reads as evening while staying tailored in cut. A dense wool blend that holds the shoulder line. Wear it with straight trousers as a suit, with jeans as a contrast, and over a fine roll-neck in winter.$q$, $q$Костюмная ткань: полиэстер 55%, вискоза 40%, эластан 5%$q$, $q$Suiting: polyester 55%, viscose 40%, elastane 5%$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1224761706-N.jpg$q$, $j$["/images/white/products/p-1224761706-b-N.jpg","/images/white/products/p-1224761706-3-N.jpg","/images/white/products/p-1224761706-s-N.jpg","/images/white/products/p-1224761706-d-N.jpg"]$j$::jsonb, NULL, 13) ON CONFLICT (id) DO NOTHING;
