INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('df233562-bf95-5ae2-9fce-a8e5ca8d05a2', 19, $q$bluzka-shkolnaya-s-volanami$q$, $q$Блузка школьная с воланами$q$, $q$School Ruffle Blouse$q$, 'dresses', $q$Оверсайз-блузка с широким воланом по груди и плечам. Мятая вискоза со льном, мягкий V-вырез, кружево на манжете.$q$, $q$An oversized blouse with a wide ruffle across the chest and shoulders. Washed viscose-linen, a soft V neck, lace at the cuff.$q$, $q$Оверсайз-блузка держится на одном приёме: широкий волан из той же ткани идёт через всю грудь и по обоим плечам, спереди и сзади, и падает примерно до локтя. Под ним корпус свободный, рукав объёмный, у запястья собран в узкую манжету с кружевом по краю. Вырез мягкий V на планке — воротника нет, гладить нечего. Ткань — вискоза со льном, та самая смесь, которую продают как французский лён: сухая мятость льна без льняной жёсткости, и она движется. Школа, офис или суббота — зависит от того, что надето снизу.$q$, $q$An oversized blouse built around one gesture: a wide ruffle of the same cloth runs right across the chest and over both shoulders, front and back, falling to about the elbow. Under it the body is generous and the sleeve is full, gathered at the wrist into a narrow cuff with a band of lace at the edge. The neckline is a soft V over a button placket — no collar, nothing to press. The cloth is viscose with linen, the blend sold as French linen: it has the dry crumple of linen without the stiffness, and it moves. School, office or a Saturday, depending on what goes under it.$q$, $q$Вискоза 70%, лён 30%$q$, $q$Viscose 70%, linen 30%$q$, $q$Машинная стирка в холодной воде, глажка до 150°$q$, $q$Machine wash cold, iron up to 150°$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1126294272-W.jpg$q$, $j$["/images/white/products/p-1126294272-b-W.jpg","/images/white/products/p-1126294272-3-W.jpg","/images/white/products/p-1126294272-s-W.jpg","/images/white/products/p-1126294272-d-T.jpg"]$j$::jsonb, NULL, 14) ON CONFLICT (id) DO NOTHING;
