INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('27ac7d49-ba70-5236-af38-c7eb28c1d5f1', 20, $q$kurtka-bomber-zamsha$q$, $q$Куртка бомбер замша$q$, $q$Suede Bomber Jacket$q$, 'outerwear', $q$Бомбер из натуральной замши — мягкий воротник, резинка по низу, свободное плечо. Осенняя верхняя одежда, которая ничего не требует.$q$, $q$A bomber in natural suede — a soft collar, an elastic hem, an easy shoulder. Autumn outerwear that asks nothing of you.$q$, $q$Бомбер скроен из натуральной замши, а не из покрытия, которое её имитирует: ворс неровно ложится на свету, а кожа по линиям сгиба со временем смягчается, вместо того чтобы трескаться. Силуэт свободный — приспущенное плечо, объёмный рукав, рубашечный воротник, который стоит или падает как оставите. По линии груди идёт шов, застёжка на скрытую молнию, поэтому поверхность ничем не разбита. Резинка собирает низ и манжеты — именно она держит форму бомбера и не пускает ветер по талии. Без подклада и лёгкий для своего тепла. Всю осень садится поверх водолазки, одинаково берёт широкие брюки и прямую юбку.$q$, $q$A bomber cut from natural suede rather than a coating that imitates it — the nap is uneven in the light and the hide softens along the fold lines with wear instead of cracking. The shape is loose: a dropped shoulder, a full sleeve, a shirt collar that stands or falls as you leave it. A seam runs across the chest and the front closes with a concealed zip, so nothing interrupts the surface. Elastic gathers the hem and the cuffs, which is what gives the bomber its shape and keeps the wind out at the waist. Unlined and light for its warmth. It sits over a roll-neck through autumn and takes wide trousers and a straight skirt equally well.$q$, $q$Натуральная замша$q$, $q$Natural suede$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1260050013-brown-Q.jpg$q$, $j$["/images/white/products/p-1260050013-brown-3-Q.jpg","/images/white/products/p-1260050013-brown-b-Q.jpg","/images/white/products/p-1260050013-brown-c-Q.jpg","/images/white/products/p-1260050013-brown-d-Q.jpg"]$j$::jsonb, $q$aw26$q$, 15) ON CONFLICT (id) DO NOTHING;
