INSERT INTO products (id, title, price, sale_price, image, images, category, sizes, model_id, color_key, color_hex, color_name_ru, color_name_en, nm, color, sku, stock_quantity, active, is_test, sort_order) VALUES ('wb-1260050015', $q$Куртка бомбер замша — Оливковый$q$, 50000, NULL, $q$/images/white/products/p-1260050013-green-Q.jpg$q$, $j$[{"src":"/images/white/products/p-1260050013-green-3-Q.jpg","alt":""},{"src":"/images/white/products/p-1260050013-green-b-Q.jpg","alt":""},{"src":"/images/white/products/p-1260050013-green-c-Q.jpg","alt":""},{"src":"/images/white/products/p-1260050013-green-d-Q.jpg","alt":""}]$j$::jsonb, 'outerwear', ARRAY['XS','S','M','L','XL'], '27ac7d49-ba70-5236-af38-c7eb28c1d5f1', $q$green$q$, $q$#6b6f4e$q$, $q$Оливковый$q$, $q$Olive$q$, 1260050015, $q$green$q$, 'WB-1260050015', 0, true, false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('1aeb77e0-9d2b-5b64-b773-c7da416ed0db', 21, $q$sportivnyy-kostyum-s-kantom$q$, $q$Спортивный костюм с кантом$q$, $q$Piped Tracksuit$q$, 'knitwear', $q$Костюм-двойка из футера — высокий ворот-стойка и контрастный кант по реглану и ноге. Продаётся только комплектом.$q$, $q$A matching fleece two-piece — a high funnel neck and contrast piping tracing the raglan and the leg. Sold as a set only.$q$, $q$Костюм, который читается как одна вещь: кант начинается у ворота, идёт по реглановому шву через плечо, по внешней стороне рукава до манжеты — и подхватывается по внешнему шву ноги. Свитшот скроен оверсайз, высокий ворот-стойка держится сам; манжеты и широкая резинка по низу собирают объём. Джоггеры прямые и свободные, талия на резинке, тот же кант по боковому шву. Плотный футер с начёсом держит форму весь день и стирается без потери цвета. Верх и низ скроены друг под друга и продаются комплектом — именно поэтому линия канта непрерывна от ворота до щиколотки.$q$, $q$A tracksuit that reads as one garment: the piping starts at the collar, runs the raglan seam over the shoulder, down the outer sleeve to the cuff — and picks up again down the outer leg. The sweatshirt is cut oversized with a high funnel neck that stands on its own; ribbed cuffs and a wide ribbed hem hold the volume. The joggers are straight and easy, an elasticated waist, the same piping on the side seam. Dense cotton fleece with a brushed back keeps its shape through the day and washes without losing colour. The two pieces are cut to each other and sold as a set — this is what makes the line of the piping continuous from collar to ankle.$q$, $q$Хлопковый футер с начёсом$q$, $q$Cotton-rich fleece$q$, $q$Деликатная стирка в холодной воде$q$, $q$Machine wash cold, gentle$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1287075011-OA.jpg$q$, $j$["/images/white/products/p-1287075011-f-OC.jpg","/images/white/products/p-1287075011-p-OB.jpg","/images/white/products/p-1287075011-b-OC.jpg","/images/white/products/p-1287075011-w-OC.jpg","/images/white/products/p-1287075011-d-OA.jpg"]$j$::jsonb, $q$aw26$q$, 16) ON CONFLICT (id) DO NOTHING;
