INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('5b959d66-d1bb-5b98-844a-dfe4bf080023', 22, $q$yubka-mini-plisse-zamshevaya$q$, $q$Юбка мини плиссе замшевая$q$, $q$Pleated Suede Mini Skirt$q$, 'skirts', $q$Мини-юбка плиссе из мягкой искусственной замши, из-под подола выглядывает белое кружево. Шлёвки, одна пуговица спереди.$q$, $q$A pleated mini in soft faux suede with a white lace underskirt peeking below the hem. Belt loops, a single front button.$q$, $q$Мини-плиссе на контрасте мягкого и чёткого: широкие бантовые складки заутюжены в искусственной замше, а из-под подола по всему кругу выглядывает белое кружево-реснички. Пояс чистый, со шлёвками и одной пуговицей — берёт тонкий ремень и так же легко обходится без него. Замша бархатистая на ощупь и держит складку, не давая ей опасть. С приталенной рубашкой юбка читается строго, с трикотажем — мягко. Кружево работает как украшение, поэтому остальной образ может молчать.$q$, $q$A pleated mini that plays soft against crisp: wide box pleats pressed into faux suede, and a white eyelash-lace underskirt showing a few centimetres below the hem all the way around. The waistband is clean, with belt loops and a single button — it takes a thin belt as easily as it goes without. The suede has a velvety hand and holds the pleat instead of collapsing it. Worn with a fitted shirt it reads polished; with a knit it goes soft. The lace does the work of an accessory, so the rest of the look can stay quiet.$q$, $q$Искусственная замша; подъюбник — кружево$q$, $q$Faux suede; lace underskirt$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1260042009-OA.jpg$q$, $j$["/images/white/products/p-1260042009-f-OA.jpg","/images/white/products/p-1260042009-b-OA.jpg","/images/white/products/p-1260042009-d-OA.jpg"]$j$::jsonb, $q$aw26$q$, 17) ON CONFLICT (id) DO NOTHING;
