INSERT INTO products (id, title, price, sale_price, image, images, category, sizes, model_id, color_key, color_hex, color_name_ru, color_name_en, nm, color, sku, stock_quantity, active, is_test, sort_order) VALUES ('wb-1260042012', $q$Юбка мини плиссе замшевая — Хаки$q$, 25000, 15000, $q$/images/white/products/p-1260042009-khaki-OA.jpg$q$, $j$[{"src":"/images/white/products/p-1260042009-khaki-f-OA.jpg","alt":""},{"src":"/images/white/products/p-1260042009-khaki-b-OA.jpg","alt":""},{"src":"/images/white/products/p-1260042009-khaki-d-OA.jpg","alt":""}]$j$::jsonb, 'skirts', ARRAY['XS','S','M','L','XL'], '5b959d66-d1bb-5b98-844a-dfe4bf080023', $q$khaki$q$, $q$#7a7458$q$, $q$Хаки$q$, $q$Khaki$q$, 1260042012, $q$khaki$q$, 'WB-1260042012', 0, true, false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('54301769-aff8-5e79-9a53-89b7cead0aac', 23, $q$yubka-plisse-dlinnaya-s-kruzhevom$q$, $q$Юбка плиссе длинная с кружевом$q$, $q$Long Pleated Lace Skirt$q$, 'skirts', $q$Длинная юбка плиссе с глубоким разрезом на белом кружеве и кружевом из-под подола. Высокий гладкий пояс.$q$, $q$A long pleated skirt with a deep front vent lined in white lace, and a lace hem showing below. High smooth waistband.$q$, $q$Длинная плиссе, построенная на одном жесте: складки застрочены по бедру, ниже раскрываются острыми ножевыми, а глубокий передний разрез при каждом шаге открывает белую кружевную вставку. То же кружево возвращается на подоле — фестончатой линией из-под тёмной ткани. Пояс высокий и гладкий. В статике юбка строгая, в движении — нет, и в этом её смысл. Объёмная блуза держит пропорции романтичными, тонкая водолазка делает их современными.$q$, $q$A long pleated skirt built on one gesture: the pleats are stitched flat over the hip, release into sharp knife pleats, and a deep front vent opens onto a white lace panel with every step. The same lace returns at the hem, showing in a scalloped line below the dark fabric. The waistband is high and smooth. Standing still the skirt is strict; walking, it is not — which is the point. A voluminous blouse keeps the proportions romantic, a fine roll-neck turns them modern.$q$, $q$Костюмная ткань; подъюбник — кружево$q$, $q$Suiting fabric; lace underskirt$q$, $q$Только химчистка$q$, $q$Dry clean only$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1263973409-OA.jpg$q$, $j$["/images/white/products/p-1263973409-f-OA.jpg","/images/white/products/p-1263973409-b-OA.jpg","/images/white/products/p-1263973409-d-OA.jpg"]$j$::jsonb, $q$aw26$q$, 18) ON CONFLICT (id) DO NOTHING;
INSERT INTO products (id, title, price, sale_price, image, images, category, sizes, model_id, color_key, color_hex, color_name_ru, color_name_en, nm, color, sku, stock_quantity, active, is_test, sort_order) VALUES ('wb-1263973409', $q$Юбка плиссе длинная с кружевом — Чёрный$q$, 25000, 15000, $q$/images/white/products/p-1263973409-OA.jpg$q$, $j$[]$j$::jsonb, 'skirts', ARRAY['XS','S','M','L','XL'], '54301769-aff8-5e79-9a53-89b7cead0aac', $q$black$q$, $q$#2b2722$q$, $q$Чёрный$q$, $q$Black$q$, 1263973409, $q$black$q$, 'WB-1263973409', 0, true, false, 0) ON CONFLICT (id) DO NOTHING;
