INSERT INTO product_models (id, model_key, slug, name_ru, name_en, category, desc_ru, desc_en, story_ru, story_en, composition_ru, composition_en, care_ru, care_en, sizes, image, gallery, season, sort_order) VALUES ('17187060-01d9-5d12-b2bd-7d405f5355be', 24, $q$rubashka-s-baskoy$q$, $q$Рубашка с баской$q$, $q$Peplum Shirt$q$, 'dresses', $q$Рубашка из плотного поплина, приталенная по корпусу и расходящаяся баской на бёдрах. Классический ворот, широкие манжеты.$q$, $q$A crisp poplin shirt fitted through the waist, flaring into a peplum over the hips. Classic collar, wide clean cuffs.$q$, $q$Рубашка с архитектурой жакета: рельефные швы стягивают поплин к талии, и от шва талии на бёдра расходится баска — линия читается даже с другого конца комнаты. Ворот классический, планка на пуговицах по всей длине, манжеты широкие и чистые. Плотный хлопок держит форму весь день. Её не заправляют: баска и есть подол — поверх юбки-карандаша, длинной плиссе или прямых брюк. Одна вещь, которая делает работу целого образа.$q$, $q$A shirt with the architecture of a jacket: princess seams draw the poplin to the waist, and from the waist seam a peplum flares over the hips — the line reads even from across a room. The collar is classic, the placket buttons through, the cuffs are wide and clean. Crisp cotton holds the shape all day. It tucks nowhere: the peplum is the hem, worn over a pencil skirt, a long pleated skirt or straight trousers. One garment that does the work of a whole outfit.$q$, $q$Хлопковый поплин$q$, $q$Cotton poplin$q$, $q$Деликатная стирка в холодной воде$q$, $q$Machine wash cold, gentle$q$, ARRAY['XS','S','M','L','XL'], $q$/images/white/products/p-1287079527-OE.jpg$q$, $j$["/images/white/products/p-1287079527-f-OE.jpg","/images/white/products/p-1287079527-b-OE.jpg","/images/white/products/p-1287079527-d-OE.jpg"]$j$::jsonb, $q$aw26$q$, 19) ON CONFLICT (id) DO NOTHING;
